import { test, expect } from '@playwright/test';

test.describe('Touch Target Size Validation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/touch-target-validation');
  });

  test('should display large enough touch targets for mobile users', async ({ page }) => {
    // Verify the page loads
    await expect(page).toBeVisible();

    // Verify the main content container is visible
    const mainContent = page.getByRole('main');
    await expect(mainContent).toBeVisible();

    // Verify the first touch target button is visible and has a minimum size
    const button1 = page.getByRole('button', { name: /submit form/i });
    await expect(button1).toBeVisible();
    const buttonBox = await button1.boundingBox();
    expect(buttonBox.width).toBeGreaterThan(44);
    expect(buttonBox.height).toBeGreaterThan(44);

    // Verify the second touch target link is visible and has a minimum size
    const link2 = page.getByRole('link', { name: /view details/i });
    await expect(link2).toBeVisible();
    const linkBox = await link2.boundingBox();
    expect(linkBox.width).toBeGreaterThan(48);
    expect(linkBox.height).toBeGreaterThan(48);

    // Verify the third touch target icon button is visible and has a minimum size
    const iconButton3 = page.getByRole('button', { name: /settings/i });
    await expect(iconButton3).toBeVisible();
    const iconBox = await iconButton3.boundingBox();
    expect(iconBox.width).toBeGreaterThan(40);
    expect(iconBox.height).toBeGreaterThan(40);

    // Verify the fourth touch target is visible and has a minimum size
    const button4 = page.getByRole('button', { name: /cancel operation/i });
    await expect(button4).toBeVisible();
    const button4Box = await button4.boundingBox();
    expect(buttonBox.width).toBeGreaterThan(40);
    expect(buttonBox.height).toBeGreaterThan(40);
  });

  test('should handle small touch targets with appropriate warning message', async ({ page }) => {
    // Navigate to the small touch target scenario
    await page.goto('/touch-target-validation/small-targets');

    // Verify the warning message is displayed
    const warningMessage = page.getByText(/touch targets are too small/i);
    await expect(warningMessage).toBeVisible();

    // Verify the warning message has a specific style
    const warningBox = await warningMessage.boundingBox();
    expect(warningBox.width).toBeGreaterThan(200);
    expect(warningBox.height).toBeGreaterThan(30);

    // Verify the small touch target button exists
    const smallButton = page.getByRole('button', { name: /small target/i });
    await expect(smallButton).toBeVisible();
    const smallBox = await smallButton.boundingBox();
    expect(smallBox.width).toBeLessThan(30);
    expect(smallBox.height).toBeLessThan(30);

    // Verify the small touch target link exists
    const smallLink = page.getByRole('link', { name: /small link/i });
    await expect(smallLink).toBeVisible();
    const smallLinkBox = await smallLink.boundingBox();
    expect(smallLinkBox.width).toBeLessThan(30);
    expect(smallLinkBox.height).toBeLessThan(30);

    // Verify the user can dismiss the warning
    const dismissButton = page.getByRole('button', { name: /dismiss warning/i });
    await expect(dismissButton).toBeVisible();
    await dismissButton.click();

    // Verify the warning message is no longer visible
    await expect(warningMessage).not.toBeVisible();
  });
});
